```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();
    int k = 3;

    // Sumy okien dlugosci k
    vector<int> wsum(n - k + 1);
    int s = 0;
    for (int i = 0; i < k; i++) s += T[i];
    wsum[0] = s;
    for (int i = 1; i <= n - k; i++) {
        s += T[i + k - 1] - T[i - 1];
        wsum[i] = s;
    }

    // maxLeft[i] = indeks okna o maks. sumie w oknach 0..i
    vector<int> maxLeft(n - k + 1);
    maxLeft[0] = 0;
    for (int i = 1; i <= n - k; i++) {
        if (wsum[i] > wsum[maxLeft[i - 1]])
            maxLeft[i] = i;
        else
            maxLeft[i] = maxLeft[i - 1];
    }

    // maxRight[i] = indeks okna o maks. sumie w oknach i..n-k
    vector<int> maxRight(n - k + 1);
    maxRight[n - k] = n - k;
    for (int i = n - k - 1; i >= 0; i--) {
        if (wsum[i] >= wsum[maxRight[i + 1]])
            maxRight[i] = i;
        else
            maxRight[i] = maxRight[i + 1];
    }

    // Najlepsza para: lewe okno konczy sie przed prawym
    int bestSum = 0, bestL = 0, bestR = 0;
    for (int i = 0; i <= n - 2 * k; i++) {
        int L = maxLeft[i];
        int R = maxRight[i + k];
        int total = wsum[L] + wsum[R];
        if (total > bestSum) {
            bestSum = total;
            bestL = L;
            bestR = R;
        }
    }

    cout << "a) Laczna suma: " << bestSum << endl;
    cout << "b) Podciag 1: pozycja=" << bestL + 1
         << ", suma=" << wsum[bestL] << endl;
    cout << "   Podciag 2: pozycja=" << bestR + 1
         << ", suma=" << wsum[bestR] << endl;
    cout << "c) Elementy 1:";
    for (int i = bestL; i < bestL + k; i++) cout << " " << T[i];
    cout << endl;
    cout << "   Elementy 2:";
    for (int i = bestR; i < bestR + k; i++) cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Obliczamy sumy wszystkich okien dlugosci k (okno przesuwne, O(n)). Prekomputujemy maxLeft[i] (najlepsze okno w zakresie 0..i) i maxRight[i] (najlepsze okno w zakresie i..n-k). Dla kazdego podzialu ciagu na lewy (0..i+k-1) i prawy (i+k..n-1), najlepsza para to maxLeft[i] + maxRight[i+k].

